// EmaVolTrend — EMA/volatility-gated trend follower for cbBTC/USDC, 1-minute bars.
//
// Idea: the dev window climbs in a few long, slow legs with noisy minutes in between.
// A slow EMA pair (30 vs 72 bars) only fires when the trend is established and still
// rising; a take-profit at +4% of position cost and a 1.5% trailing stop from the
// position's peak value bank each leg, and a 30-bar cooldown after every exit keeps
// the bot from churning on the whipsaw minutes between legs. An ATR-style filter
// (mean absolute 1-minute log return over 30 bars) keeps entries out of dead-flat
// stretches where a round trip cannot pay its ~30-45 bps of fees, slippage and
// impact. A 5% equity drawdown guard flattens the position and halts trading.
//
// Sizing: the whole cash balance on each entry. The pool is deep (~590k USDC), so a
// full-size fill still costs only ~17 bps of impact each way; splitting would not
// pay less, and cash earns nothing while flat.
//
// Determinism: only float64 arithmetic on the closes (+ - * / and Math.log), seeded
// exactly like the EMAs below; no clock, no environment, no randomness.

import { BPS, runBars, type Bar, type BarsState, type BuyInput, type SellInput } from './vendor/makefun-bars.ts';

const SYMBOL = 'CBBTC';
/** Fast and slow EMA spans, in bars. */
const FAST_SPAN = 30;
const SLOW_SPAN = 72;
/** The slow EMA must still be rising over this many bars back for an entry. */
const SLOPE_LOOKBACK = 10;
/** ATR-style volatility window (bars) and entry floor (mean |1m log return|, bps). */
const VOL_WINDOW = 30;
const VOL_FLOOR_BPS = 2;
/** Take profit: position value at least this many bps over its cost. */
const TAKE_PROFIT_BPS = 400;
/** Trailing stop: position value this many bps under its peak value. */
const TRAIL_BPS = 150;
/** Bars to wait after an exit fill before a new entry. */
const COOLDOWN_BARS = 30;
/** Equity drawdown from peak (bps) that flattens the position and halts trading. */
const DRAWDOWN_GUARD_BPS = 500;
/** Max slippage vs the latest close, bps. */
const MAX_SLIPPAGE_BPS = 100;

const BPS_F = 10000;

/** One EMA: closes seen until it starts, then its value. */
interface Ema {
  span: number;
  warm: number[];
  value: number | null;
}

function emaStep(e: Ema, close: number): void {
  if (e.value !== null) {
    e.value += (2 / (e.span + 1)) * (close - e.value);
    return;
  }
  e.warm.push(close);
  if (e.warm.length === e.span) {
    let sum = 0;
    for (const x of e.warm) sum += x;
    e.value = sum / e.span;
  }
}

const fast: Ema = { span: FAST_SPAN, warm: [], value: null };
const slow: Ema = { span: SLOW_SPAN, warm: [], value: null };
/** Slow EMA values, one per bar, for the rising-trend check. */
const slowHistory: (number | null)[] = [];
/** |1m log return| in bps, last VOL_WINDOW bars, for the volatility filter. */
const absReturns: number[] = [];
let prevClose: number | null = null;
/** Peak position value (quote units) since the current entry. */
let peakPositionValue = 0n;
/** Seq of the bar whose batch reported the latest sell fill. */
let lastExitSeq = -1000000;
/** Peak equity (quote units) seen so far. */
let peakEquity: bigint | null = null;
/** Latched once the drawdown guard trips. */
let halted = false;

function pushBar(bar: Bar): void {
  const c = Number(bar.c);
  if (prevClose !== null && prevClose > 0) {
    absReturns.push(Math.abs(Math.log(c / prevClose)) * BPS_F);
    if (absReturns.length > VOL_WINDOW) absReturns.shift();
  }
  prevClose = c;
  emaStep(fast, c);
  emaStep(slow, c);
  slowHistory.push(slow.value);
}

function meanAbsReturnBps(): number {
  if (absReturns.length === 0) return 0;
  let sum = 0;
  for (const x of absReturns) sum += x;
  return sum / absReturns.length;
}

function slowRising(): boolean {
  const n = slowHistory.length;
  if (n <= SLOPE_LOOKBACK) return false;
  const now = slowHistory[n - 1];
  const then = slowHistory[n - 1 - SLOPE_LOOKBACK];
  return now !== null && now !== undefined && then !== null && then !== undefined && now > then;
}

await runBars({
  onBatch(state: BarsState, batch) {
    for (const fill of batch.fills) {
      if (fill.side === 'sell' && fill.status === 'filled') lastExitSeq = state.seq;
    }
    for (const bar of batch.bars) {
      if (bar.symbol === SYMBOL) pushBar(bar);
    }
    if (state.warmingUp) return [];

    // Drawdown guard: flatten once, then halt for the rest of the window.
    if (peakEquity === null || state.equity > peakEquity) peakEquity = state.equity;
    if (!halted && peakEquity > 0n) {
      const drawdownBps = Number(((peakEquity - state.equity) * BigInt(BPS_F)) / peakEquity);
      if (drawdownBps >= DRAWDOWN_GUARD_BPS) halted = true;
    }

    const held = state.positions.get(SYMBOL);
    const orders: (BuyInput | SellInput)[] = [];
    if (held !== undefined) {
      const value = state.value(SYMBOL, held.qty);
      if (value > peakPositionValue) peakPositionValue = value;
      let exit = halted;
      if (!exit && fast.value !== null && slow.value !== null && fast.value <= slow.value) exit = true;
      if (!exit && value * BigInt(BPS_F) >= held.cost * BigInt(BPS_F + TAKE_PROFIT_BPS)) exit = true;
      if (!exit && peakPositionValue > 0n && value * BigInt(BPS_F) <= peakPositionValue * BigInt(BPS_F - TRAIL_BPS)) exit = true;
      if (exit) {
        orders.push({ side: 'sell', symbol: SYMBOL, qty: held.qty, max_slippage_bps: MAX_SLIPPAGE_BPS });
        peakPositionValue = 0n;
      }
      return orders;
    }

    // Flat: no entries while halted, cooling down, or warming the indicators.
    if (halted) return [];
    if (state.seq - lastExitSeq < COOLDOWN_BARS) return [];
    if (fast.value === null || slow.value === null) return [];
    if (fast.value <= slow.value) return [];
    if (!slowRising()) return [];
    if (meanAbsReturnBps() < VOL_FLOOR_BPS) return [];

    let notional = state.cash;
    const room = state.weightRoom(SYMBOL);
    if (room < notional) notional = room;
    if (notional <= 0n || notional < BigInt(state.hello.fees.min_notional_quote_units)) return [];
    peakPositionValue = 0n;
    return [{ side: 'buy', symbol: SYMBOL, notional_quote_units: notional, max_slippage_bps: MAX_SLIPPAGE_BPS }];
  },
});

// DipSnap RSI mean-reversion bot for btc-race-24h-20261123-0511.
// makefun anchor a034ea3a3b3f3df8148e3652e873f87447083df3 round 34206147
// (quoted from `makefun init` before this file's first write.)
//
// Strategy: long-only RSI(21) dip buyer on CBBTC/USDC, 1-minute bars.
//   - Flat: buy 100% of cash when RSI(21) closes below 35 (oversold dip).
//   - In position: sell everything when RSI(21) closes above 75, or the
//     position is up +0.8% / down -0.8% against its cost basis.
//   - Drawdown guard: if equity falls 8% from its running peak, flatten
//     and sit out 60 bars.
// Orders decided on bar k fill at bar k+1's open, so every decision uses
// only closes already seen. Fully deterministic: no clock, no randomness,
// no environment reads; all state comes from the harness batches.

import { runBars } from './vendor/makefun-bars.ts';
import type { BarsState, Batch, OrderInput } from './vendor/makefun-bars.ts';

const SYMBOL = 'CBBTC';
const RSI_PERIOD = 21;
const BUY_RSI = 35;
const EXIT_RSI = 75;
const TAKE_PROFIT = 0.008;
const STOP_LOSS = -0.008;
const DD_GUARD = 0.08;
const COOLDOWN_BARS = 60;
const MAX_SLIPPAGE_BPS = 200;

const closes: number[] = [];
const seedGains: number[] = [];
const seedLosses: number[] = [];
let avgGain = 0;
let avgLoss = 0;
let rsiSeeded = false;
let rsi: number | null = null;
let peakEquity = 1000_000_000n; // quote units (micro-USDC)
let coolUntilSeq = -1;

function updateRsi(close: bigint): void {
  // Prices are integers at price_scale 5; work in USDC per BTC
  // (price raw / 1e5) as floats for the RSI only. Decisions use only
  // these deterministic floats derived from bar closes.
  const px = Number(close) / 100000;
  if (closes.length > 0) {
    const diff = px - closes[closes.length - 1];
    const gain = diff > 0 ? diff : 0;
    const loss = diff < 0 ? -diff : 0;
    if (!rsiSeeded) {
      seedGains.push(gain);
      seedLosses.push(loss);
      if (seedGains.length === RSI_PERIOD) {
        avgGain = seedGains.reduce((a, b) => a + b, 0) / RSI_PERIOD;
        avgLoss = seedLosses.reduce((a, b) => a + b, 0) / RSI_PERIOD;
        rsiSeeded = true;
        rsi = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
      }
    } else {
      avgGain = (avgGain * (RSI_PERIOD - 1) + gain) / RSI_PERIOD;
      avgLoss = (avgLoss * (RSI_PERIOD - 1) + loss) / RSI_PERIOD;
      rsi = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
    }
  }
  closes.push(px);
}

await runBars({
  onBatch(state: BarsState, _batch: Batch): OrderInput[] {
    const bar = state.latest.get(SYMBOL);
    if (bar === undefined) return [];
    updateRsi(BigInt(bar.c));

    const equity = state.equity;
    if (equity > peakEquity) peakEquity = equity;

    if (state.warmingUp) return [];
    if (rsi === null) return [];
    if (state.seq <= coolUntilSeq) return [];

    const pos = state.positions.get(SYMBOL);
    const qty = pos?.qty ?? 0n;

    if (qty === 0n) {
      if (rsi < BUY_RSI && state.cash > 0n) {
        return [{
          side: 'buy',
          symbol: SYMBOL,
          notional_quote_units: state.cash,
          max_slippage_bps: MAX_SLIPPAGE_BPS,
        }];
      }
      return [];
    }

    // In position: check exits.
    const cost = pos?.cost ?? 0n;
    const value = state.value(SYMBOL, qty);
    const ret = cost > 0n ? Number(value - cost) / Number(cost) : 0;
    const drawdown = peakEquity > 0n ? Number(peakEquity - equity) / Number(peakEquity) : 0;

    if (rsi > EXIT_RSI || ret >= TAKE_PROFIT || ret <= STOP_LOSS || drawdown >= DD_GUARD) {
      if (drawdown >= DD_GUARD) coolUntilSeq = state.seq + COOLDOWN_BARS;
      return [{
        side: 'sell',
        symbol: SYMBOL,
        qty,
        max_slippage_bps: MAX_SLIPPAGE_BPS,
      }];
    }
    return [];
  },
});

