import sys, math
sys.path.insert(0, "/home/hatch/workspace/makefun-btc-race-1123/dev-syukuran")
from sim import run, closes, bars, N

def ema_series(span):
    out=[None]*N; s=0.0
    for i,c in enumerate(closes):
        if i<span:
            s+=c
            if i==span-1: out[i]=s/span
        else: out[i]=out[i-1]+(2/(span+1))*(c-out[i-1])
    return out

def rsi_series(period=14):
    out=[None]*N; gains=[]; losses=[]; ag=al=None
    for i in range(1,N):
        d=closes[i]-closes[i-1]; g,l=max(d,0),max(-d,0)
        if ag is None:
            gains.append(g); losses.append(l)
            if len(gains)==period:
                ag=sum(gains)/period; al=sum(losses)/period
                out[i]=100 if al==0 else 100-100/(1+ag/al)
        else:
            ag=(ag*(period-1)+g)/period; al=(al*(period-1)+l)/period
            out[i]=100 if al==0 else 100-100/(1+ag/al)
    return out

F12=ema_series(12); F48=ema_series(48); F8=ema_series(8); F21=ema_series(21)
R14=rsi_series(14); R21=rsi_series(21)

def show(name, r):
    print(f"{name:52s} pnl={r['pnl']:+7.2f} trades={r['trades']:2d} maxDD={r['max_dd']*100:5.2f}% fees={r['fees']:.2f}")

# ---- DipTurn family (1118 design, fresh test on this window) ----
def dipturn(drop_bps=90, lookback=60, confirm_bps=10, low_win=16, tp=175, trail=100, arm=30, stop=250, tail=60):
    st={"peak":0.0,"last_exit":-10**6}
    def decide(s):
        k=s["k"]; c=closes[k]
        if k>=tail and s["qty"]==0 and k < N-tail:
            if k-lookback>=0:
                drop=(closes[k-lookback]/c-1)*1e4
                low=min(bars[i]["l"] for i in range(k-low_win+1,k+1))
                if drop>=drop_bps and (c/low-1)*1e4>=confirm_bps:
                    return 'buy'
            return None
        if s["qty"]>0:
            if c>st["peak"]: st["peak"]=c
            ret=(c/s["entry_px"]-1)*1e4
            if ret>=tp: st["peak"]=0.0; return 'sell'
            if st["peak"]>0 and ret>=arm and (st["peak"]/c-1)*1e4>=trail: st["peak"]=0.0; return 'sell'
            if ret<=-stop: st["peak"]=0.0; return 'sell'
        return None
    return decide

for drop,tp,trail in [(90,175,100),(60,175,100),(90,250,120),(70,200,100),(90,300,150),(120,250,120),(60,300,150)]:
    show(f"DipTurn drop{drop} tp{tp} trail{trail}", run(dipturn(drop_bps=drop,tp=tp,trail=trail)))

# ---- TrendDip hybrid: uptrend filter + dip entry, ride the leg ----
def trenddip(ema_f=12, ema_s=48, dip_bps=60, dip_win=30, tp=300, trail=150, arm=50, stop=200, rsi_max=50, cool=15):
    F=ema_series(ema_f); S=ema_series(ema_s)
    st={"peak":0.0,"last_exit":-10**6}
    def decide(s):
        k=s["k"]; c=closes[k]
        if s["qty"]>0:
            if c>st["peak"]: st["peak"]=c
            ret=(c/s["entry_px"]-1)*1e4
            if ret>=tp: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if ret>=arm and (st["peak"]/c-1)*1e4>=trail: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if ret<=-stop: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if F[k] is not None and S[k] is not None and F[k]<=S[k]: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            return None
        if k-st["last_exit"]<cool: return None
        if F[k] is None or S[k] is None or F[k]<=S[k]: return None
        if k>10 and (S[k]<=S[k-10]): return None
        hi=max(closes[i] for i in range(k-dip_win+1,k+1))
        if (hi/c-1)*1e4 < dip_bps: return None
        if R14[k] is not None and R14[k]>rsi_max: return None
        return 'buy'
    return decide

for dip,tp,trail in [(60,300,150),(80,300,150),(50,400,200),(60,400,200),(100,300,150),(60,250,120),(40,300,150)]:
    show(f"TrendDip dip{dip} tp{tp} trail{trail}", run(trenddip(dip_bps=dip,tp=tp,trail=trail)))

# ---- Fast EMA cross ride: EMA8/21, wide trail, no TP ----
def fastcross(tp=None, trail=200, stop=150, cool=20):
    st={"peak":0.0,"last_exit":-10**6}
    def decide(s):
        k=s["k"]; c=closes[k]
        if s["qty"]>0:
            if c>st["peak"]: st["peak"]=c
            ret=(c/s["entry_px"]-1)*1e4
            if tp and ret>=tp: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if (st["peak"]/c-1)*1e4>=trail: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if ret<=-stop: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            return None
