        if F8[k] is None or F21[k] is None: return None
        if F8[k]>F21[k] and F8[k-1]<=F21[k-1]: return 'buy'
        return None
    return decide

for tp,trail in [(None,200),(None,150),(400,150),(None,250),(300,200)]:
    show(f"FastCross tp{tp} trail{trail}", run(fastcross(tp=tp,trail=trail)))

# ---- Momentum ignition: 60m return > X and trend up ----
def ignition(ret_bps=60, tp=300, trail=150, stop=200, cool=30):
    st={"peak":0.0,"last_exit":-10**6}
    def decide(s):
        k=s["k"]; c=closes[k]
        if s["qty"]>0:
            if c>st["peak"]: st["peak"]=c
            ret=(c/s["entry_px"]-1)*1e4
            if ret>=tp: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if (st["peak"]/c-1)*1e4>=trail: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            if ret<=-stop: st["peak"]=0.0; st["last_exit"]=k; return 'sell'
            return None
        if k-st["last_exit"]<cool: return None
        if k<60: return None
        if (c/closes[k-60]-1)*1e4>=ret_bps and F12[k] is not None and F48[k] is not None and F12[k]>F48[k]:
            return 'buy'
